### C++

```cpp
#include <iostream>
#include <vector>
#include <queue>
using namespace std;

const long long LIMIT = (long long)1e18;

struct Edge {
    int to;
    long long w;
};

// 返回 ans[1..n]，无解返回空 vector
vector<long long> solve_case(int n, const vector<vector<Edge>>& g) {
    vector<long long> dist(n + 1, 0);
    vector<int> visited(n + 1, 0);
    vector<long long> ans(n + 1, 0);

    queue<int> q;

    for (int start = 1; start <= n; start++) {
        if (visited[start]) {
            continue;
        }

        vector<int> comp;
        visited[start] = 1;
        dist[start] = 0;
        q.push(start);

        long long mn = 0;
        long long mx = 0;

        while (!q.empty()) {
            int u = q.front();
            q.pop();
            comp.push_back(u);

            if (dist[u] < mn) {
                mn = dist[u];
            }
            if (dist[u] > mx) {
                mx = dist[u];
            }

            for (const Edge& e : g[u]) {
                int v = e.to;
                long long nd = dist[u] + e.w;

                if (!visited[v]) {
                    visited[v] = 1;
                    dist[v] = nd;
                    q.push(v);
                } else {
                    // 已访问的点必须满足相对值一致
                    if (dist[v] != nd) {
                        return {};
                    }
                }
            }
        }

        // 平移使最小读数变为 1
        long long add = 1 - mn;
        if (mx + add > LIMIT) {
            return {};
        }

        for (int u : comp) {
            ans[u] = dist[u] + add;
        }
    }

    return ans;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T;
    cin >> T;

    while (T--) {
        int n, m;
        cin >> n >> m;

        vector<vector<Edge>> g(n + 1);

        for (int t = 0; t < m; t++) {
            int i, j;
            long long k;
            cin >> i >> j >> k;

            g[j].push_back({i, k});
            g[i].push_back({j, -k});
        }

        vector<long long> res = solve_case(n, g);

        if (res.empty()) {
            cout << -1 << '\n';
        } else {
            for (int i = 1; i <= n; i++) {
                if (i > 1) {
                    cout << ' ';
                }
                cout << res[i];
            }
            cout << '\n';
        }
    }

    return 0;
}
